def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max((v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]

    # Each non-background marker projects along its row and column.
    # Projection stops at the next marker in that direction, or at the grid edge.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] != bg:
                        break
                    out[rr][cc] = 3
                    rr += dr
                    cc += dc
    return out
